//! Every Mermaid diagram type ODiagramador offers: id, names (PT/EN), the header keywords that select it,
//! and an offline digest of its official docs (`docs/syntax/mermaid`, regenerated by
//! `scripts/sync-mermaid-docs.py`). Used for "new diagram", templates and `get_syntax_help`.

use serde::Serialize;

use crate::Lang;

pub struct Kind {
    pub id: &'static str,
    pub en: &'static str,
    pub pt: &'static str,
    /// Header keywords (lowercase prefixes) that identify the type in a source / help topic.
    pub aliases: &'static [&'static str],
    /// ELK, dragging and exact positions apply (graph diagrams).
    pub graph: bool,
    pub reference: &'static str,
}

macro_rules! doc {
    ($f:literal) => {
        include_str!(concat!("../../../docs/syntax/mermaid/", $f, ".md"))
    };
}

