/// The kind named by an id, a Mermaid header ("quadrantChart", "xychart-beta", "C4Context") or a type
/// reported by Mermaid ("flowchart-v2", "classDiagram").
pub fn find(name: &str) -> Option<&'static Kind> {
    let n = name.trim().to_ascii_lowercase();
    if n.is_empty() {
        return None;
    }
    KINDS.iter().find(|k| k.id == n).or_else(|| KINDS.iter().find(|k| k.aliases.iter().any(|a| n.starts_with(a))))
}

impl Kind {
    pub fn label(&self, lang: Lang) -> &'static str {
        if lang == Lang::PtBr {
            self.pt
        } else {
            self.en
        }
    }

    /// First example of the official docs: a valid starting point for a new diagram.
    pub fn example(&self) -> Option<String> {
        let start = self.reference.find("```mermaid\n")? + "```mermaid\n".len();
        let end = self.reference[start..].find("\n```")?;
        Some(format!("{}\n", &self.reference[start..start + end]))
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct KindInfo {
    pub kind: &'static str,
    pub label: &'static str,
    pub graph: bool,
}

/// For "new diagram" pickers.
pub fn list(lang: Lang) -> Vec<KindInfo> {
    KINDS.iter().map(|k| KindInfo { kind: k.id, label: k.label(lang), graph: k.graph }).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_kind_has_an_example_and_resolves_its_headers() {
        for k in KINDS {
            let ex = k.example().unwrap_or_else(|| panic!("{} has no example", k.id));
            assert!(!ex.trim().is_empty());
            assert_eq!(find(k.id).map(|f| f.id), Some(k.id));
        }
        assert_eq!(find("quadrantChart").unwrap().id, "quadrant");
        assert_eq!(find("xychart-beta").unwrap().id, "xychart");
        assert_eq!(find("C4Context").unwrap().id, "c4");
        assert_eq!(find("flowchart-v2").unwrap().id, "flowchart");
        assert_eq!(find("erDiagram").unwrap().id, "er");
        assert_eq!(find("railroadEbnf").unwrap().id, "railroad");
        assert!(find("nothing").is_none());
    }
}
